import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom"; // para navegación
import './Administrativas.css';

export default function Administrativas() {
  const navigate = useNavigate();
  const chatEndRef = useRef(null);

  const [messages, setMessages] = useState([
    { type: "bot", content: "options", timestamp: new Date() },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false);

  const predefinedOptions = [
    { img: "/item-chat.png", text: "Kardex" },
    { img: "/item-chat.png", text: "Constancia" },
    { img: "/item-chat.png", text: "Titulacion" },
    { img: "/item-chat.png", text: "Creditos" },
    { img: "/item-chat.png", text: "Mas opciones..." },
  ];

  const additionalOptions = [
    { img: "/item-chat.png", text: "Historial Academico" },
    { img: "/item-chat.png", text: "Pagos y Finanzas" },
    { img: "/item-chat.png", text: "Horarios" },
  ];

  // Hace scroll al último mensaje
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleOptionClick = (option) => {
    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages([
        ...messages,
        { type: "user", content: option, timestamp: new Date() },
        { type: "bot", content: "moreOptions", timestamp: new Date() },
        {
          type: "bot",
          content:
            "Si no se encuentra la opcion que usted busca, favor de escribirla en el chat.",
          timestamp: new Date(),
        },
      ]);
    } else {
      const newMessages = [
        ...messages,
        { type: "user", content: option, timestamp: new Date() },
      ];
      setMessages(newMessages);

      // Simula respuesta del bot
      setTimeout(() => simulateBotResponse(option, newMessages), 500);
    }
  };

  const simulateBotResponse = (option, currentMessages) => {
    const botResponse = { type: "bot", content: "", timestamp: new Date() };

    if (option.toLowerCase().includes("evaluacion") || option.toLowerCase().includes("profesores")) {
      botResponse.content = `Para el proceso de evaluacion de docentes se tiene que hacer lo siguiente:

1.- Tienes que entrar al SIM con tu numero de control y contraseña.
2.-Te iras al modulo de evaluaciones y encuestas.
3.- Ahi te aparecera una tabla con todas las evaluaciones posibles, tendras que darle en la opcion que tu buscas.
4.- Por ultimo tendras que contestar todas la preguntas.`;

      setMessages([
        ...currentMessages,
        botResponse,
        {
          type: "bot",
          content:
            'Si quiere cambiar de proceso, presione "Cambiar", si quiere irse al menu principal, presione "Salir".',
          timestamp: new Date(),
          actions: [
            { label: "Cambiar", action: "change" },
            { label: "Salir", action: "exit" },
          ],
        },
      ]);
    } else {
      botResponse.content = `Has seleccionado: ${option}. ¿En qué puedo ayudarte con esto?`;
      setMessages([...currentMessages, botResponse]);
    }
  };

  const handleSendMessage = () => {
    if (inputValue.trim()) {
      const newMessages = [
        ...messages,
        { type: "user", content: inputValue, timestamp: new Date() },
      ];
      setMessages(newMessages);
      setInputValue("");
      setTimeout(() => simulateBotResponse(inputValue, newMessages), 500);
    }
  };

  const handleActionClick = (action) => {
    if (action === "change") {
      setMessages([{ type: "bot", content: "options", timestamp: new Date() }]);
      setShowMoreOptions(false);
    } else if (action === "exit") {
      navigate("/");
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="administrativas-container">
      {/* Header */}
      <header className="administrativas-header">
        <button className="name-button" onClick={() => navigate("/")}>TalkinPon</button>
        <div className="title-logo">
          <h1>Administrativas</h1>
          <div className="heade-logo">
            <img src="/logo-app.png" alt="Logo" />
          </div>
        </div>
      </header>

      {/* Chat Area */}
      <div className="chat-area">
        {messages.map((message, index) => (
          <div key={index} className={`chat-message ${message.type}`}>
            <div className="avatar">
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "User"}
              />
            </div>

            {message.content === "options" ? (
              <div className="options-box">
                <h3>Elige una opcion.</h3>
                {predefinedOptions.map((option, idx) => (
                  <button key={idx} onClick={() => handleOptionClick(option.text)}>
                    <img src={option.img} alt={option.text} className="option-img" />
                    <span>{option.text}</span>
                  </button>
                ))}
              </div>
            ) : message.content === "moreOptions" ? (
              <div className="options-box">
                <h3>Mas opciones disponibles:</h3>
                {additionalOptions.map((option, idx) => (
                  <button key={idx} onClick={() => handleOptionClick(option.text)}>
                    <img src={option.img} alt={option.text} className="option-img" />
                    <span>{option.text}</span>
                  </button>
                ))}
              </div>
            ) : (
              <div className={`message-box ${message.type}`}>
                <p>{message.content}</p>
              </div>
            )}

            {message.actions && message.actions.length > 0 && (
            <div className="actions-row">
                {message.actions.map((action, idx) => (
                <button key={idx} onClick={() => handleActionClick(action.action)} className="action-button">
                    {action.label}
                </button>
                ))}
            </div>
            )}
          </div>
        ))}
        <div ref={chatEndRef}></div>
      </div>

      {/* Input Area */}
      <div className="input-area">
        <input
          type="text"
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Pregunta lo que quieres...."
        />
        <button onClick={handleSendMessage} className="send-button">Enviar</button>
      </div>
    </div>
  );
}
